import { Container } from 'pixi.js';
import gsap from 'gsap';

export abstract class BaseChip extends Container {

    protected _id: number;
    public get id(): number {
        return this._id;
    }

    private _selected: boolean = false;
    public get selected(): boolean {
        return this._selected;
    }

    protected _value: number;
    public get value(): number {
        return this._value;
    }

    protected _selectable: boolean = true;
    public get selectable(): boolean {
        return this._selectable;
    }

    constructor(id: number) {
        super();
        this._id = id;
    }

    public abstract showValue(): void;
    public abstract hideValue(): void;
    public abstract enterCabinetMode(): void;

    public setSelected(selected: boolean, instant: boolean = false, updateFunction?: () => void, scales: { selected: number, unSelected: number } = { selected: 1, unSelected: 0.8 }): void {
        gsap.killTweensOf(this);
        const targetScale: number = selected ? scales.selected : scales.unSelected;
        if (!instant) {
            gsap.to(this.scale, { x: targetScale, y: targetScale , duration: 0.3, onUpdate: updateFunction, ease: 'none' });
        } else {
            this.scale.set(targetScale);
            if (updateFunction) {
                updateFunction();
            }
        }
        this._selected = selected;
    }

    public enterChipSelect(returnedToSelector: boolean): void {
        if (!this.renderable) {
            this.renderable = true;
            if (!returnedToSelector) {
                gsap.killTweensOf(this);
                this.scale.set(0);
                gsap.to(this.scale, { x: 1, y: 1, duration: 0.5, ease: 'bounce.out' });
            }
        }
    }

    public startDraggingOffChipHolder(): void {
        this.renderable = false;
    }
}